    for i in range(1, 2 * n, 2):
        parent = int(data[i - 1]) - 1
        child = int(data[i]) - 1
        tree[child].append(parent)
    def dfs(node: int, parent: int, depth: int) -> int:
        for v in tree[node]:
            if v == parent:
                continue
            depth += dfs(v, node, depth)
        return depth
    depths = [dfs(i, -1, 0) for i in range(n)]
