def solution(input_str: str) -> str:
    data = [tuple(map(int, line.split())) for line in input_str.strip().split('\n')]
    polygon = sorted(data)
    length = len(polygon)

    if length == 2:
        dist = math.hypot(polygon[0][0] - polygon[1][0], polygon[0][1] - polygon[1][1])
        return str(dist)

    lengths = [0] * length  # end of path distance for each point: route end on p[i]
    lengths[-1] = math.dist(polygon[-1], polygon[-2])
    for i in range(length - 1, 0, -1):
        lengths[i - 1] = math.hypot(polygon[i - 1][0] - polygon[i][0], polygon[i - 1][1] - polygon[i][1])
    max_len = 0
    for i in range(1, length):
        total = lengths[i - 1] + lengths[i] + lengths[i - 1]
        if total > max_len:
            max_len = total
    return str(max_len)

